import { lazy, Suspense, useEffect, useRef, useState } from 'react';
import { toast } from 'sonner';
import CaixaEditor, { EtapaSomenteLeitura, etapasConsulta } from './CaixaEditor';
import { money, request } from './api';
import { formatDate, formatDateTime, formatDay, formatWeekday, mesAtual, parseDate } from './datas';
import UnitMultiSelect from './UnitMultiSelect';
import ResumoColaboradores from './ResumoColaboradores';
import DataInput from './DataInput';
import { MoneyInput } from './inputs';
import MaquininhaForm from './MaquininhaForm';
import Paginacao, { paginar, paginaValida } from './Paginacao';
import Cofre from './Cofre';
import Motivos from './Motivos';
import CargosEPerfis, { SEM_CARGO, type FiltroUsuarios } from './Cargos';
import NomeEditavel from './NomeEditavel';
import { DialogosProvider, useDialogos } from './dialogos';
import { Icone } from './icones';
import type { DetalheCaixa } from './pdfCaixa';
import { bateu, CENTAVO, corDiferenca, descreverQuebra, divergeCartoes, formasPagamento, quebraDinheiro, statusCaixa, type Acesso } from './quebra';
import { limites } from '../../server/src/limites';
import { nomesCargos as cargoOptions } from '../../server/src/cargos';

type User = { id: number; nome: string; email: string; tipo: string };
type Unit = { id: number; nome: string; troco_continua?: number; tolerancia_dinheiro?: number; fechamento_cego?: number };
type Machine = { id: number; nome: string; numero: string; numero_serie: string };
type Close = { id: number; usuario_id: number; unidade_id: number; unidade_nome: string; usuario_nome: string; saldo_inicial: number; total_entradas: number; total_maquininhas: number; total_saidas: number; diferenca_dinheiro?: number; diferenca_cartoes?: number; tolerancia_dinheiro: number; status: string; problema_resolvido: number | null; finalizado_em: string | null; criado_em: string; data_caixa: string; turno: string; pode_editar: boolean };


type FiltroCaixas = { de: string; ate: string; unidades: number[]; situacao: string; status: string; turno: string; responsavel: string };
// abre (e volta ao limpar) no mês corrente
const filtroPadrao = (): FiltroCaixas => { const mes = mesAtual(); return { de: formatDay(mes.de), ate: formatDay(mes.ate), unidades: [], situacao: '', status: '', turno: '', responsavel: '' }; };
// período pelo dia do caixa, o mesmo exibido na tabela e usado nos relatórios
const dentroDoPeriodo = (item: Close, filtro: FiltroCaixas) => { const dia = item.data_caixa; const [inicio, fim] = [parseDate(filtro.de), parseDate(filtro.ate)]; return (!inicio || dia >= inicio) && (!fim || dia <= fim); };
// a diferença de um caixa em aberto ainda é parcial, então ele não entra nos filtros de situação
const passaNoFiltro = (item: Close, filtro: FiltroCaixas) =>
  dentroDoPeriodo(item, filtro) &&
  (!filtro.responsavel || item.usuario_id === Number(filtro.responsavel)) &&
  (!filtro.unidades.length || filtro.unidades.includes(item.unidade_id)) &&
  (!filtro.turno || item.turno === filtro.turno) &&
  (!filtro.status || item.status === filtro.status) &&
  (!filtro.situacao || (item.status !== 'aberto' && (filtro.situacao === 'bateu' ? bateu(item) === true : filtro.situacao === 'nao-bateu' ? bateu(item) === false : filtro.situacao === 'cartoes' ? divergeCartoes(item) : quebraDinheiro(item) === filtro.situacao)));
const acessoPadrao: Acesso = { ve_diferenca: false, escolhe_data_caixa: false };

// os gráficos (recharts) só são baixados quando o dono abre Relatórios
const Relatorios = lazy(() => import('./Relatorios'));
// jsPDF só é baixado quando alguém exporta
const baixarPdfCaixa = async (data: DetalheCaixa, userName: string) => (await import('./pdfCaixa')).exportarPdfCaixa(data, userName);

export default function App() {
  const [user, setUser] = useState<User | null>(null);
  // primeiro acesso: usuário cadastrado pelo dono cria a senha com o código que recebeu
  const [modo, setModo] = useState<'login' | 'cadastro' | 'primeiro-acesso'>('login');
  const [email, setEmail] = useState('');
  const [senha, setSenha] = useState('');
  const [nome, setNome] = useState('');
  const [codigo, setCodigo] = useState('');
  const [confirmacao, setConfirmacao] = useState('');
  const [error, setError] = useState('');
  useEffect(() => { if (localStorage.getItem('token')) request('/auth/me').then((data) => setUser(data.usuario)).catch(() => localStorage.removeItem('token')); }, []);
  const trocarModo = (novo: typeof modo) => { setModo(novo); setError(''); setSenha(''); setConfirmacao(''); };
  async function submitAuth(event: React.FormEvent) {
    event.preventDefault(); setError('');
    const rota = { login: '/auth/login', cadastro: '/auth/register', 'primeiro-acesso': '/auth/primeiro-acesso' }[modo];
    const body = modo === 'login' ? { email, senha } : modo === 'cadastro' ? { nome, email, senha, confirmacao } : { email, codigo, senha, confirmacao };
    try { const data = await request(rota, { method: 'POST', body: JSON.stringify(body) }); if (modo === 'cadastro') { trocarModo('login'); setError('Cadastro realizado. Faça seu login.'); } else { localStorage.setItem('token', data.token); setUser(data.usuario); } } catch (err) { if (modo === 'login' && (err as { status?: number }).status === 403) trocarModo('primeiro-acesso'); setError((err as Error).message); }
  }
  const textos = { login: ['Entrar no sistema', 'Use seus dados para continuar.', 'Acessar painel'], cadastro: ['Criar acesso', 'Seu e-mail define automaticamente o perfil do dono.', 'Cadastrar usuário'], 'primeiro-acesso': ['Primeiro acesso', 'Informe o código que você recebeu e crie sua senha.', 'Criar senha e entrar'] }[modo];
  if (!user) return <main className="auth-shell"><section className="auth-copy"><span className="eyebrow">OPERAÇÃO / CONTROLE</span><h1>Fechamento de caixa, sem ruído.</h1><p>Uma visão clara para cada unidade, maquininha e conferência da rede.</p><div className="metric-line"><strong>04</strong><span>unidades prontas para operar</span></div></section><form className="auth-card" onSubmit={submitAuth}><div className="brand-mark">FC</div><h2>{textos[0]}</h2><p className="muted">{textos[1]}</p>{modo === 'cadastro' && <label>Nome de exibição<input value={nome} onChange={(event) => setNome(event.target.value)} maxLength={limites.nomeUsuario} required /></label>}<label>E-mail<input type="email" value={email} onChange={(event) => setEmail(event.target.value)} maxLength={limites.email} required /></label>{modo === 'primeiro-acesso' && <label>Código de acesso<input className="codigo-input" value={codigo} onChange={(event) => setCodigo(event.target.value.toUpperCase())} placeholder="XXXX-XXXX" autoComplete="one-time-code" autoCapitalize="characters" spellCheck={false} maxLength={limites.codigoAcesso} required /></label>}<label>{modo === 'primeiro-acesso' ? 'Crie sua senha' : 'Senha'}<input type="password" value={senha} onChange={(event) => setSenha(event.target.value)} autoComplete={modo === 'login' ? 'current-password' : 'new-password'} minLength={8} maxLength={limites.senhaBytes} required /></label>{modo !== 'login' && <label>Confirmar senha<input type="password" value={confirmacao} onChange={(event) => setConfirmacao(event.target.value)} autoComplete="new-password" minLength={8} maxLength={limites.senhaBytes} required /></label>}{error && <div className="alert">{error}</div>}<button className="primary" type="submit">{textos[2]}</button>{modo === 'login' ? <><button className="link-button" type="button" onClick={() => trocarModo('primeiro-acesso')}>Primeiro acesso: tenho um código</button><button className="link-button link-button-junto" type="button" onClick={() => trocarModo('cadastro')}>Ainda não tenho acesso</button></> : <button className="link-button" type="button" onClick={() => trocarModo('login')}>{modo === 'cadastro' ? 'Já tenho uma conta' : 'Já tenho uma senha'}</button>}</form></main>;
  return <DialogosProvider><Dashboard user={user} onLogout={() => { localStorage.removeItem('token'); setUser(null); }} /></DialogosProvider>;
}
function Dashboard({ user, onLogout }: { user: User; onLogout: () => void }) {
  const [view, setView] = useState('visao-geral'); const [units, setUnits] = useState<Unit[]>([]); const [closes, setCloses] = useState<Close[]>([]); const [filtro, setFiltro] = useState<FiltroCaixas>(filtroPadrao); const [abaCaixas, setAbaCaixas] = useState<'lista' | 'colaboradores'>('lista'); const [acesso, setAcesso] = useState<Acesso>(acessoPadrao); const [editor, setEditor] = useState<{ id: number | null } | null>(null); const [menuAberto, setMenuAberto] = useState(false); const atrasoMenu = useRef<number>(undefined); const toqueAbriuMenu = useRef(false); const hoje = new Date(); const [selectedClose, setSelectedClose] = useState<number | null>(null);
  const ultimaCarga = useRef(0); const [recarga, setRecarga] = useState(0); const [pagina, setPagina] = useState(1);
  useEffect(() => setPagina(1), [filtro]);
  // resposta de uma carga já superada é descartada; falha avisa em vez de deixar dados velhos sem aviso
  const refresh = () => { const carga = ++ultimaCarga.current; Promise.all([request('/unidades'), request('/fechamentos'), request('/acesso')]).then(([unidades, caixas, permissoes]) => { if (carga !== ultimaCarga.current) return; setUnits(unidades); setCloses(caixas); setAcesso(permissoes); }).catch((err) => toast.error((err as Error).message)); }; useEffect(refresh, []);
  const goTo = (next: string) => { setEditor(null); setView(next); fecharMenu(); refresh(); setRecarga((valor) => valor + 1); };
  const openClose = (item: Close) => item.status === 'aberto' && item.pode_editar ? setEditor({ id: item.id }) : setSelectedClose(item.id);
  const openCloses = closes.filter((item) => item.status === 'aberto');
  const verResumo = (user.tipo === 'admin' || user.tipo === 'dono') && acesso.ve_diferenca;
  const aba = verResumo ? abaCaixas : 'lista';
  // no resumo por colaborador, situação e status não se aplicam: distorceriam a proporção de caixas que não bateram
  const filtroAplicado = aba === 'colaboradores' ? { ...filtro, situacao: '', status: '' } : filtro;
  const responsaveis = [...new Map(closes.map((item) => [item.usuario_id, item.usuario_nome])).entries()].sort((a, b) => a[1].localeCompare(b[1]));
  const closesFiltrados = closes.filter((item) => passaNoFiltro(item, filtroAplicado)); const paginaAtual = paginaValida(pagina, closesFiltrados.length); const diferencaFiltrada = closesFiltrados.filter((item) => item.status !== 'aberto').reduce((sum, item) => sum + (item.diferenca_dinheiro ?? 0), 0);
  
  const finalizados = closes.filter((item) => item.status !== 'aberto'); const quebraTotal = finalizados.reduce((sum, item) => sum + (item.diferenca_dinheiro ?? 0), 0); const cartoesTotal = finalizados.reduce((sum, item) => sum + (item.diferenca_cartoes ?? 0), 0); const pending = closes.filter((item) => item.status === 'finalizado' && bateu(item) === false).length; const aguardando = closes.filter((item) => item.status === 'finalizado').length;
  // padrão único do menu: trilho de ícones que abre por cima do conteúdo (mouse com atraso para não abrir só de cruzar, foco, toque ou ☰ no celular)
  // e fecha ao sair, ao escolher um item, ao tocar fora ou com Esc
  const abrirMenuComAtraso = () => { atrasoMenu.current = window.setTimeout(() => setMenuAberto(true), 120); };
  const fecharMenu = () => { window.clearTimeout(atrasoMenu.current); toqueAbriuMenu.current = false; setMenuAberto(false); };
  useEffect(() => { if (!menuAberto) return; const fecharComEsc = (event: KeyboardEvent) => { if (event.key === 'Escape') fecharMenu(); }; window.addEventListener('keydown', fecharComEsc); return () => window.removeEventListener('keydown', fecharComEsc); }, [menuAberto]);
  return <div className={`app-shell ${menuAberto ? 'menu-aberto' : ''}`}><aside onMouseEnter={abrirMenuComAtraso} onMouseLeave={fecharMenu} onFocus={(event) => { if (event.target.matches(':focus-visible')) setMenuAberto(true); }} onBlur={(event) => { if (!event.currentTarget.contains(event.relatedTarget) && !event.currentTarget.matches(':hover')) fecharMenu(); }} onPointerDownCapture={(event) => { if (event.pointerType === 'touch' && !menuAberto) { toqueAbriuMenu.current = true; setMenuAberto(true); } }} onPointerCancelCapture={() => { toqueAbriuMenu.current = false; }} onClickCapture={(event) => { if (toqueAbriuMenu.current) { toqueAbriuMenu.current = false; event.preventDefault(); event.stopPropagation(); } }}><div className="side-brand"><span className="brand-mark small">FC</span><div><strong>FECHA<br />CAIXA</strong><small>REDE OPERACIONAL</small></div></div><div className="side-date" title={`${formatWeekday(hoje)}, ${formatDate(hoje)}`}><span className="side-date-full">{formatWeekday(hoje)}<strong>{formatDate(hoje)}</strong></span><strong className="side-date-short">{formatDate(hoje).slice(0, 5)}</strong></div><nav><div className="nav-label">OPERACIONAL</div><button className={view === 'visao-geral' ? 'active' : ''} title="Visão geral" onClick={() => goTo('visao-geral')}><Icone nome="visaoGeral" /><span>Visão geral</span></button><button className={view === 'historico' ? 'active' : ''} title="Caixas fechados" onClick={() => goTo('historico')}><Icone nome="caixas" /><span>Caixas fechados</span></button>{user.tipo === 'dono' && <button className={view === 'cofre' ? 'active' : ''} title="Cofre" onClick={() => goTo('cofre')}><Icone nome="cofre" /><span>Cofre</span></button>}{user.tipo === 'dono' && <><div className="nav-label">RELATÓRIOS</div><button className={view === 'relatorios' ? 'active' : ''} title="Relatórios" onClick={() => goTo('relatorios')}><Icone nome="relatorios" /><span>Relatórios</span></button></>}{(user.tipo === 'admin' || user.tipo === 'dono') && <><div className="nav-label">CADASTROS</div><button className={view === 'usuarios' ? 'active' : ''} title="Usuários" onClick={() => goTo('usuarios')}><Icone nome="usuarios" /><span>Usuários</span></button><button className={view === 'maquininhas' ? 'active' : ''} title="Maquininhas" onClick={() => goTo('maquininhas')}><Icone nome="maquininhas" /><span>Maquininhas</span></button><button className={view === 'motivos' ? 'active' : ''} title="Motivos de saída" onClick={() => goTo('motivos')}><Icone nome="motivos" /><span>Motivos de saída</span></button></>}{user.tipo === 'dono' && <button className={view === 'unidades' ? 'active' : ''} title="Unidades" onClick={() => goTo('unidades')}><Icone nome="unidades" /><span>Unidades</span></button>}</nav><div className="side-user"><div className="avatar" title={`${user.nome} (${roleLabel(user.tipo)})`}>{user.nome.slice(0, 1).toUpperCase()}</div><div><strong>{user.nome}</strong><small>{roleLabel(user.tipo)}</small></div><button type="button" title="Sair" onClick={onLogout}><Icone nome="sair" /><span>Sair</span></button></div></aside>{menuAberto && <div className="menu-fundo" onClick={fecharMenu} />}<main className="content"><header><div><button type="button" className="menu-mobile" aria-label="Abrir menu" aria-expanded={menuAberto} onClick={() => setMenuAberto(true)}><Icone nome="menu" /></button><h1>{editor ? 'Caixa' : view === 'visao-geral' ? 'Visão geral' : view === 'historico' ? 'Caixas fechados' : view === 'usuarios' ? 'Usuários' : view === 'maquininhas' ? 'Maquininhas' : view === 'relatorios' ? 'Relatórios' : view === 'cofre' ? 'Cofre' : view === 'motivos' ? 'Motivos de saída' : 'Unidades'}</h1></div>{view === 'visao-geral' && !editor && <button className="primary header-action" onClick={() => setEditor({ id: null })}><Icone nome="adicionar" /> Abrir caixa</button>}</header>{editor && <CaixaEditor key={editor.id ?? 'novo'} id={editor.id} units={units} acesso={acesso} onExit={() => { setEditor(null); refresh(); }} onFinalized={() => { setEditor(null); refresh(); toast.success('Caixa finalizado.'); }} />}{!editor && view === 'visao-geral' && <><section className="stats"><article><span>Caixas no período</span><strong>{closes.length}</strong><small>{openCloses.length} em aberto</small></article>{acesso.ve_diferenca ? <><article><span>Diferenças pendentes</span><strong className={pending ? 'orange' : ''}>{pending}</strong><small>Fora da tolerância, sem conferência</small></article><article><span>Quebra de dinheiro</span><strong className={corDiferenca(quebraTotal)}>{money(quebraTotal)}</strong><small>Cartões/Pix: {money(cartoesTotal)}</small></article></> : <><article><span>Aguardando conferência</span><strong>{aguardando}</strong><small>Finalizados, ainda não conferidos</small></article><article><span>Conferidos</span><strong>{closes.filter((item) => item.status === 'conferido').length}</strong><small>Fechamento cego: a diferença fica com o gestor</small></article></>}</section>{openCloses.length > 0 && <section className="panel open-closes"><div className="panel-heading"><div><span className="eyebrow">EM ANDAMENTO</span><h2>Caixas em aberto</h2></div></div><div className="table-wrap"><table><thead><tr><th>Aberto em</th><th>Unidade</th><th>Turno</th><th>Responsável</th><th></th></tr></thead><tbody>{openCloses.map((item) => <tr key={item.id}><td>{formatDateTime(item.criado_em)}</td><td><strong className="texto-livre">{item.unidade_nome}</strong></td><td>{item.turno}</td><td><span className="texto-livre">{item.usuario_nome}</span></td><td>{item.pode_editar ? <button className="ghost" onClick={() => setEditor({ id: item.id })}>Continuar <Icone nome="avancar" /></button> : <button className="ghost" onClick={() => setSelectedClose(item.id)}>Ver</button>}</td></tr>)}</tbody></table></div></section>}<section className="panel"><div className="panel-heading"><div><span className="eyebrow">ACOMPANHAMENTO</span><h2>Atividade recente</h2></div><button className="ghost" onClick={() => goTo('historico')}>Ver todos <Icone nome="avancar" /></button></div><CloseTable closes={closes.slice(0, 6)} userName={user.nome} onOpen={openClose} /></section></>}{!editor && view === 'historico' && <section className="panel">{verResumo && <div className="abas" role="tablist"><button type="button" role="tab" aria-selected={aba === 'lista'} className={aba === 'lista' ? 'active' : ''} onClick={() => setAbaCaixas('lista')}>Caixas</button><button type="button" role="tab" aria-selected={aba === 'colaboradores'} className={aba === 'colaboradores' ? 'active' : ''} onClick={() => setAbaCaixas('colaboradores')}>Por colaborador</button></div>}<div className="filters close-filters report-filters"><label className="report-date">De<DataInput label="Data inicial" value={filtro.de} onChange={(de) => setFiltro({ ...filtro, de })} /></label><label className="report-date">Até<DataInput label="Data final" value={filtro.ate} onChange={(ate) => setFiltro({ ...filtro, ate })} /></label><UnitMultiSelect units={units} value={filtro.unidades} onChange={(unidades) => setFiltro({ ...filtro, unidades })} ariaLabel="Filtrar por unidades" />{aba === 'lista' && acesso.ve_diferenca && <select aria-label="Situação" value={filtro.situacao} onChange={(event) => setFiltro({ ...filtro, situacao: event.target.value })}><option value="">Todas as situações</option><option value="nao-bateu">Não bateu</option><option value="falta">Falta de dinheiro</option><option value="sobra">Sobra de dinheiro</option><option value="cartoes">Divergência em cartões/Pix</option><option value="bateu">Bateu</option></select>}{aba === 'lista' && <select aria-label="Status" value={filtro.status} onChange={(event) => setFiltro({ ...filtro, status: event.target.value })}><option value="">Todos os status</option><option value="aberto">Em aberto</option><option value="finalizado">Aguardando conferência</option><option value="conferido">Conferido</option></select>}<select aria-label="Turno" value={filtro.turno} onChange={(event) => setFiltro({ ...filtro, turno: event.target.value })}><option value="">Todos os turnos</option><option value="ALMOÇO">Almoço</option><option value="JANTAR">Jantar</option></select>{responsaveis.length > 1 && <select aria-label="Responsável" value={filtro.responsavel} onChange={(event) => setFiltro({ ...filtro, responsavel: event.target.value })}><option value="">Todos os responsáveis</option>{responsaveis.map(([id, nome]) => <option key={id} value={id}>{nome}</option>)}</select>}{JSON.stringify(filtro) !== JSON.stringify(filtroPadrao()) && <button className="ghost" onClick={() => setFiltro(filtroPadrao())}>Limpar filtros</button>}</div>{aba === 'lista' ? <><div className="filter-summary">{closesFiltrados.length} {closesFiltrados.length === 1 ? 'caixa' : 'caixas'}{acesso.ve_diferenca && <> · quebra de dinheiro somada (sem os em aberto): <strong className={corDiferenca(diferencaFiltrada)}>{money(diferencaFiltrada)}</strong></>}</div><CloseTable closes={paginar(closesFiltrados, paginaAtual)} userName={user.nome} onOpen={openClose} onDeleted={user.tipo === 'dono' ? refresh : undefined} /><Paginacao total={closesFiltrados.length} pagina={paginaAtual} onChange={setPagina} /></> : <ResumoColaboradores caixas={closesFiltrados} onSelecionar={(usuarioId) => { setFiltro({ ...filtro, responsavel: String(usuarioId) }); setAbaCaixas('lista'); }} />}</section>}{!editor && view === 'usuarios' && <Users isOwner={user.tipo === 'dono'} units={units} recarga={recarga} />}{!editor && view === 'maquininhas' && <Machines units={units} recarga={recarga} />}{!editor && view === 'unidades' && <Units units={units} refresh={refresh} />}{!editor && view === 'motivos' && <Motivos recarga={recarga} />}{!editor && view === 'cofre' && <Cofre units={units} recarga={recarga} onAbrirCaixa={setSelectedClose} />}{!editor && view === 'relatorios' && <Suspense fallback={<section className="panel"><p className="muted">Carregando relatórios…</p></section>}><Relatorios units={units} recarga={recarga} /></Suspense>}</main>{selectedClose !== null && <CloseDetails id={selectedClose} isOwner={user.tipo === 'dono'} onClose={() => setSelectedClose(null)} onEdit={(id) => { setSelectedClose(null); refresh(); setEditor({ id }); }} onUpdated={() => { refresh(); toast.success('Conferência atualizada.'); }} />}</div>;
}

function CloseTable({ closes, userName, onOpen, onDeleted }: { closes: Close[]; userName: string; onOpen: (item: Close) => void; onDeleted?: () => void }) { const { confirmar } = useDialogos(); async function deleteClose(event: React.MouseEvent, item: Close) { event.stopPropagation(); if (!await confirmar({ titulo: 'Excluir caixa', mensagem: <>O caixa de <strong>{item.unidade_nome}</strong> ({item.turno === 'JANTAR' ? 'jantar' : 'almoço'} de {formatDay(item.data_caixa)}, {item.usuario_nome}) será excluído com todas as etapas. Esta ação não pode ser desfeita.</>, confirmar: 'Excluir caixa', perigo: true })) return; try { await request(`/fechamentos/${item.id}`, { method: 'DELETE' }); onDeleted?.(); toast.success('Caixa excluído.'); } catch (error) { toast.error((error as Error).message); } } async function exportClose(event: React.MouseEvent, id: number) { event.stopPropagation(); try { await baixarPdfCaixa(await request(`/fechamentos/${id}`), userName); } catch (error) { toast.error((error as Error).message); } } return <div className="table-wrap"><table className="close-table"><colgroup><col className="col-data" /><col className="col-turno" /><col /><col /><col className="col-valor" /><col className="col-valor" /><col className="col-status" /><col className="col-acoes" /></colgroup><thead><tr><th>Data</th><th>Turno</th><th>Unidade</th><th>Responsável</th><th>Dinheiro</th><th>Cartões/Pix</th><th>Status</th><th>Ações</th></tr></thead><tbody>{closes.length ? closes.map((item) => <tr className="clickable-row" key={item.id} onClick={() => onOpen(item)}><td>{formatDay(item.data_caixa)}</td><td>{item.turno === 'JANTAR' ? 'Jantar' : 'Almoço'}</td><td title={item.unidade_nome}><strong>{item.unidade_nome}</strong></td><td title={item.usuario_nome}>{item.usuario_nome}</td>{[item.diferenca_dinheiro, item.diferenca_cartoes].map((valor, index) => <td key={index} className={`close-diff ${item.status === 'aberto' || valor === undefined ? '' : corDiferenca(valor)}`}>{item.status === 'aberto' || valor === undefined ? '—' : money(valor)}</td>)}<td><span className={`status ${item.status} ${item.problema_resolvido === 1 ? 'status-certo' : item.problema_resolvido === 0 ? 'status-errado' : ''}`}>{statusCaixa(item)}</span></td><td><div className="row-actions"><button type="button" className="row-action" title="Exportar PDF" aria-label="Exportar PDF" onClick={(event) => exportClose(event, item.id)}><Icone nome="baixar" /> PDF</button>{onDeleted && <button type="button" className="row-action row-action-danger" title="Excluir caixa" aria-label="Excluir caixa" onClick={(event) => deleteClose(event, item)}><Icone nome="lixeira" /></button>}</div></td></tr>) : <tr><td colSpan={8} className="empty">Nenhum fechamento encontrado.</td></tr>}</tbody></table></div>; }

function CloseDetails({ id, isOwner, onClose, onUpdated, onEdit }: { id: number; isOwner: boolean; onClose: () => void; onUpdated: () => void; onEdit: (id: number) => void }) {
  const { confirmar } = useDialogos();
  const [data, setData] = useState<any>(null);
  const [error, setError] = useState('');
  const [aba, setAba] = useState<number | null>(null); // null = Resumo
  const [salvando, setSalvando] = useState(false);
  useEffect(() => { request(`/fechamentos/${id}`).then(setData).catch((err) => setError(err.message)); }, [id]);
  // escolher outra decisão substitui a anterior; desfazer devolve o caixa para a fila de conferência
  async function conferir(decisao: boolean | null, desfazer = false) {
    setSalvando(true);
    try { await request(`/fechamentos/${id}/conferir`, { method: 'POST', body: JSON.stringify({ problema_resolvido: decisao, desmarcar: desfazer }) }); setData({ ...data, fechamento: { ...data.fechamento, status: desfazer ? 'finalizado' : 'conferido', problema_resolvido: desfazer || decisao === null ? null : decisao ? 1 : 0 } }); onUpdated(); } catch (err) { toast.error((err as Error).message); } finally { setSalvando(false); }
  }
  async function reopenClose() {
    const atual = data.fechamento;
    const conferido = atual.status === 'conferido';
    const resultado = atual.problema_resolvido === 1 ? ' como Certo' : atual.problema_resolvido === 0 ? ' como Errado' : '';
    const mensagem = conferido
      ? <>Este caixa foi conferido{atual.conferido_por_nome && <> por <strong>{atual.conferido_por_nome}</strong></>}{resultado}. Ao reabrir, essa conferência é apagada: o caixa volta para "Em aberto" e terá que ser finalizado e conferido de novo.</>
      : <>O caixa volta para "Em aberto" e sai da fila de conferência até ser finalizado de novo.</>;
    if (!await confirmar({ titulo: 'Reabrir caixa', mensagem, confirmar: 'Reabrir caixa', perigo: conferido })) return;
    try { await request(`/fechamentos/${id}/reabrir`, { method: 'POST' }); onEdit(id); } catch (err) { toast.error((err as Error).message); } }
  if (error) return <div className="modal-backdrop"><section className="modal"><div className="alert">{error}</div><div className="modal-footer"><button type="button" className="ghost" onClick={onClose}>Fechar</button></div></section></div>;
  if (!data) return <div className="modal-backdrop"><section className="modal"><p className="muted">Carregando detalhes do caixa...</p></section></div>;
  const close = data.fechamento;
  const fechado = close.status !== 'aberto';
  const decisao = close.status !== 'conferido' ? undefined : close.problema_resolvido === 1 ? true : close.problema_resolvido === 0 ? false : null;
  const botaoDecisao = (valor: boolean | null, rotulo: string, classe: string) => <button type="button" className={classe} aria-pressed={decisao === valor} disabled={salvando} onClick={() => { if (decisao !== valor) conferir(valor); }}>{rotulo}</button>;
  const autoria = `Caixa do dia ${formatDay(close.data_caixa)} · ` + (fechado ? `Finalizado por ${close.usuario_nome} em ${formatDateTime(close.finalizado_em || close.criado_em)}` : `Aberto por ${close.usuario_nome} em ${formatDateTime(close.criado_em)}`);
  const entradas = data.entradas.filter((entry: any) => entry.valor > 0);
  // mesmas contas de recalcularDiferencas (server/src/db.ts), com os valores à mostra
  const vendasDinheiro: number = data.entradas.find((entry: any) => entry.forma_pagamento === 'dinheiro')?.valor ?? 0;
  const esperadoGaveta = close.saldo_inicial + vendasDinheiro - close.total_saidas;
  const sentido = (valor: number, positivo: string, negativo: string) => Math.abs(valor) <= CENTAVO ? 'bateu' : valor > 0 ? positivo : negativo;
  const valoresCaixa: [string, number, string][] = [['Saldo inicial', close.saldo_inicial, 'Dinheiro na gaveta ao abrir o caixa'], ['Entradas do sistema', close.total_entradas, 'Vendas registradas, todas as formas'], ['Maquininhas', close.total_maquininhas, 'Soma dos relatórios das maquininhas'], ['Dinheiro físico', close.dinheiro_fisico, 'Dinheiro contado ao fechar'], ['Saídas', close.total_saidas, 'Dinheiro retirado da gaveta']];
  const nivel = (titulo: string, explicacao: string) => <div className="detail-nivel"><span className="eyebrow">{titulo}</span><small>{explicacao}</small></div>;
  const linhas = (itens: any[], vazio: string, rotulo: (item: any) => React.ReactNode) => itens.length ? itens.map((item) => <div key={item.id}><span>{rotulo(item)}</span><strong>{money(item.valor)}</strong></div>) : <p className="muted">{vazio}</p>;
  return <div className="modal-backdrop"><section className="modal detail-modal">
    <div className="modal-head"><div>
      <span className="eyebrow">CONSULTA DO FECHAMENTO #{close.id}</span>
      <h2>{close.unidade_nome}</h2>
      <div className="detail-meta"><span title={significadoStatus[statusCaixa(close)]} className={`status ${close.status} ${close.problema_resolvido === 1 ? 'status-certo' : close.problema_resolvido === 0 ? 'status-errado' : ''}`}>{statusCaixa(close)}</span><span>{close.turno === 'JANTAR' ? 'Jantar' : 'Almoço'}</span><span className="detail-autor" title={autoria}>{autoria}</span></div>
    </div><button type="button" className="close" aria-label="Fechar" title="Fechar" onClick={onClose}><Icone nome="fechar" /></button></div>
    <div className="caixa-steps detail-abas" role="tablist">{[null, ...etapasConsulta.map((_, indice) => indice)].map((indice) => <button key={indice ?? 'resumo'} type="button" role="tab" aria-selected={aba === indice} className={aba === indice ? 'active' : ''} onClick={() => setAba(indice)}>{indice === null ? 'Resumo' : `${indice + 1}. ${etapasConsulta[indice]}`}</button>)}</div>
    {aba === null ? <>
      {fechado && nivel('RESULTADO', 'O que foi contado comparado com o que o sistema esperava. Valor positivo é sobra; negativo, falta.')}
      {fechado && (close.diferenca_dinheiro === undefined
        ? <p className="muted detail-verdict">Fechamento cego: a diferença é conferida pelo gestor.</p>
        : <div className="detail-resultado">
          <div><span>Quebra de dinheiro · {sentido(close.diferenca_dinheiro, 'sobra', 'falta')}</span><strong className={corDiferenca(close.diferenca_dinheiro)}>{money(close.diferenca_dinheiro)}</strong><small>Contado {money(close.dinheiro_fisico)} − esperado na gaveta {money(esperadoGaveta)}</small><small>Esperado = saldo inicial {money(close.saldo_inicial)} + vendas em dinheiro {money(vendasDinheiro)} − saídas {money(close.total_saidas)}</small></div>
          <div><span>Cartões/Pix · {sentido(close.diferenca_cartoes, 'maquininhas acima do sistema', 'maquininhas abaixo do sistema')}</span><strong className={corDiferenca(close.diferenca_cartoes)}>{money(close.diferenca_cartoes)}</strong><small>Maquininhas {money(close.total_maquininhas)} − vendas em cartão, Pix e vales no sistema {money(close.total_entradas - vendasDinheiro)}</small></div>
          <p>{descreverQuebra(close)}<small>Tolerância no dinheiro: {money(close.tolerancia_dinheiro ?? 0)}. Cartões/Pix precisam bater exato.</small></p>
        </div>)}
      {nivel('VALORES DO CAIXA', 'Totais informados em cada etapa do fechamento; são a base do resultado acima.')}
      <div className="detail-grid">{valoresCaixa.map(([rotulo, valor, ajuda]) => <div key={rotulo}><span>{rotulo}</span><strong>{money(valor)}</strong><small>{ajuda}</small></div>)}</div>
      {nivel('DETALHAMENTO', 'Os lançamentos que compõem os totais.')}
      <div className="detail-secoes">
        <section><h3>Entradas por forma de pagamento</h3><div className="detail-list">{linhas(entradas, 'Nenhuma entrada informada.', (entry) => formasPagamento[entry.forma_pagamento] ?? entry.forma_pagamento)}</div></section>
        <section><h3>Relatórios das maquininhas</h3><div className="detail-list">{linhas(data.maquininhas, 'Nenhuma maquininha informada.', (machine) => `${machine.nome} · nº ${machine.numero} · série ${machine.numero_serie}`)}</div></section>
        <section><h3>Saídas de dinheiro</h3><div className="detail-list">{linhas(data.saidas, 'Nenhuma saída registrada.', (exit) => exit.observacao ? `${exit.motivo} · ${exit.observacao}` : exit.motivo)}</div></section>
      </div>
    </> : <EtapaSomenteLeitura etapa={aba} data={data} />}
    <div className="modal-footer">{isOwner && fechado && <div className="conferencia" role="group" aria-label="Conferência do dono"><span className="eyebrow">CONFERÊNCIA</span>{botaoDecisao(null, 'Conferido', 'secondary')}{botaoDecisao(true, 'Certo', 'primary')}{botaoDecisao(false, 'Errado', 'danger')}{decisao !== undefined && <button type="button" className="ghost" disabled={salvando} onClick={() => conferir(null, true)}>Desfazer conferência</button>}</div>}<button type="button" className="ghost" onClick={onClose}>Fechar</button>{close.pode_editar && close.status !== 'aberto' && !(close.status === 'conferido' && !isOwner) && <button type="button" className="secondary" onClick={reopenClose}>Reabrir para editar</button>}{close.pode_editar && close.status === 'aberto' && <button type="button" className="primary" onClick={() => onEdit(id)}>Continuar caixa</button>}</div>
  </section></div>;
}

// explicação dos rótulos de statusCaixa (quebra.ts), mostrada na dica do selo da consulta
const significadoStatus: Record<string, string> = {
  'Em aberto': 'O caixa ainda está sendo preenchido; os valores são parciais.',
  Finalizado: 'Finalizado no fechamento cego; a diferença é avaliada por quem confere.',
  Bateu: 'Finalizado com o dinheiro dentro da tolerância e cartões/Pix batendo; aguarda conferência.',
  Pendente: 'Finalizado com diferença fora da tolerância (dinheiro) ou em cartões/Pix; aguarda conferência.',
  Conferido: 'O dono conferiu o caixa sem marcar se estava certo ou errado.',
  'Conferido/Certo': 'O dono conferiu e marcou o caixa como certo.',
  'Conferido/Errado': 'O dono conferiu e marcou o caixa como errado.'
};
const roleLabel = (tipo: string) => tipo === 'funcionario' ? 'Colaborador' : tipo === 'admin' ? 'Admin' : 'Dono';
type Usuario = { id: number; nome: string; email: string; tipo: string; cargo: string | null; ativo: number; criado_em: string; primeiro_acesso: number; unidades: number[] };
// abre (e volta ao limpar) só com os ativos: os inativos aparecem pela situação
const filtroUsuariosPadrao: FiltroUsuarios = { perfil: '', cargo: '', unidades: [], situacao: 'ativos' };
// o dono acessa todas as unidades, então entra em qualquer filtro de unidade
const usuarioPassaNoFiltro = (item: Usuario, filtro: FiltroUsuarios) =>
  (!filtro.perfil || item.tipo === filtro.perfil) &&
  (!filtro.cargo || (filtro.cargo === SEM_CARGO ? !item.cargo : item.cargo === filtro.cargo)) &&
  (!filtro.unidades.length || item.tipo === 'dono' || item.unidades.some((id) => filtro.unidades.includes(id))) &&
  (!filtro.situacao || (filtro.situacao === 'ativos') === !!item.ativo);

function Users({ isOwner, units, recarga }: { isOwner: boolean; units: Unit[]; recarga: number }) {
  const { avisar, confirmar } = useDialogos();
  const [users, setUsers] = useState<Usuario[]>([]); const [editing, setEditing] = useState<Usuario | null>(null); const [criando, setCriando] = useState(false); const [verCargos, setVerCargos] = useState(false);
  const [filtro, setFiltro] = useState<FiltroUsuarios>(filtroUsuariosPadrao); const [pagina, setPagina] = useState(1);
  useEffect(() => setPagina(1), [filtro]);
  const refresh = () => request('/usuarios').then(setUsers).catch((err) => toast.error((err as Error).message));
  useEffect(() => { refresh(); }, [recarga]);
  const filtrados = users.filter((item) => usuarioPassaNoFiltro(item, filtro)); const paginaAtual = paginaValida(pagina, filtrados.length);
  // cargos antigos fora da lista continuam no filtro enquanto alguém os tiver
  const cargosDoFiltro = [...new Set([...cargoOptions, ...users.map((item) => item.cargo).filter((cargo): cargo is string => !!cargo)])];
  async function inativar(item: Usuario) {
    if (!await confirmar({ titulo: 'Inativar usuário', mensagem: <><strong>{item.nome}</strong> ({item.email}) perde o acesso ao sistema na hora. Os caixas já registrados continuam em Caixas fechados. O usuário pode ser reativado depois, com o mesmo cargo e as mesmas unidades, na situação Inativos.</>, confirmar: 'Inativar usuário', perigo: true })) return;
    try { await request(`/usuarios/${item.id}`, { method: 'DELETE' }); refresh(); toast.success('Usuário inativado.'); } catch (err) { toast.error((err as Error).message); }
  }
  async function reativar(item: Usuario) { try { await request(`/usuarios/${item.id}/reativar`, { method: 'POST' }); refresh(); toast.success(`${item.nome} voltou a ter acesso.`); } catch (err) { toast.error((err as Error).message); } }
  const acoes = (item: Usuario) => !item.ativo ? <button type="button" className="row-action" title="Reativar usuário" aria-label={`Reativar usuário ${item.nome}`} onClick={() => reativar(item)}>Reativar</button>
    : <><button type="button" className="ghost" onClick={(event) => { event.stopPropagation(); setEditing(item); }}>Editar</button>{item.tipo !== 'dono' && <button type="button" className="row-action row-action-danger" title="Inativar usuário" aria-label={`Inativar usuário ${item.nome}`} onClick={(event) => { event.stopPropagation(); inativar(item); }}><Icone nome="inativar" /></button>}</>;
  return <section className="panel"><div className="panel-heading usuarios-cabecalho"><div><span className="eyebrow">ACESSOS</span><h2>Usuários cadastrados</h2></div><div className="row-actions"><button type="button" className="ghost" onClick={() => setVerCargos(true)}><Icone nome="cargos" /> Cargos e perfis</button>{isOwner && <button type="button" className="primary" onClick={() => setCriando(true)}><Icone nome="adicionar" /> Novo usuário</button>}</div></div><div className="filters close-filters"><UnitMultiSelect units={units} value={filtro.unidades} onChange={(unidades) => setFiltro({ ...filtro, unidades })} ariaLabel="Filtrar por unidade vinculada" /><select aria-label="Perfil" value={filtro.perfil} onChange={(event) => setFiltro({ ...filtro, perfil: event.target.value })}><option value="">Todos os perfis</option><option value="funcionario">Colaborador</option><option value="admin">Admin</option><option value="dono">Dono</option></select><select aria-label="Cargo" value={filtro.cargo} onChange={(event) => setFiltro({ ...filtro, cargo: event.target.value })}><option value="">Todos os cargos</option>{cargosDoFiltro.map((cargo) => <option key={cargo} value={cargo}>{cargo}</option>)}<option value={SEM_CARGO}>Sem cargo</option></select><select aria-label="Situação" value={filtro.situacao} onChange={(event) => setFiltro({ ...filtro, situacao: event.target.value })}><option value="ativos">Ativos</option><option value="inativos">Inativos</option><option value="">Ativos e inativos</option></select>{JSON.stringify(filtro) !== JSON.stringify(filtroUsuariosPadrao) && <button className="ghost" onClick={() => setFiltro(filtroUsuariosPadrao)}>Limpar filtros</button>}</div><div className="filter-summary">{filtrados.length} {filtrados.length === 1 ? 'usuário' : 'usuários'}</div><div className="table-wrap"><table><thead><tr><th>Nome</th><th>E-mail</th><th>Perfil</th><th>Cargo</th><th>Unidades</th><th>Cadastro</th>{isOwner && <th></th>}</tr></thead><tbody>{paginar(filtrados, paginaAtual).map((item) => <tr key={item.id} {...(isOwner && item.ativo ? { className: 'clickable-row', title: 'Clique para editar o usuário', onClick: () => setEditing(item) } : { className: item.ativo ? undefined : 'linha-inativa' })}><td><div className="usuario-nome"><strong className="texto-livre">{item.nome}</strong>{!item.ativo ? <span className="status inativo" title="Sem acesso ao sistema; pode ser reativado">Inativo</span> : !!item.primeiro_acesso && <span className="status aguardando" title="Cadastrado pelo dono; ainda não criou a senha">Aguardando 1º acesso</span>}</div></td><td><span className="texto-livre">{item.email}</span></td><td><span className="status">{roleLabel(item.tipo)}</span></td><td>{item.cargo || '—'}</td><td><span className="texto-livre">{item.tipo === 'dono' ? 'Todas' : units.filter((unit) => item.unidades.includes(unit.id)).map((unit) => unit.nome).join(', ') || '—'}</span></td><td>{formatDate(item.criado_em)}</td>{isOwner && <td><div className="row-actions">{acoes(item)}</div></td>}</tr>)}{!filtrados.length && <tr><td className="empty" colSpan={isOwner ? 7 : 6}>Nenhum usuário encontrado com esses filtros.</td></tr>}</tbody></table></div><Paginacao total={filtrados.length} pagina={paginaAtual} onChange={setPagina} />{verCargos && <CargosEPerfis usuarios={users} onFiltrar={(filtroCargo) => { setFiltro({ ...filtroUsuariosPadrao, ...filtroCargo }); setVerCargos(false); }} onClose={() => setVerCargos(false)} />}{criando &&<UserModal units={units} onClose={() => setCriando(false)} onSaved={({ usuario, codigo }) => { setCriando(false); refresh(); if (codigo) avisar({ titulo: 'Usuário cadastrado', mensagem: <CodigoAcesso usuario={usuario} codigo={codigo} /> }); }} />}{editing && <UserModal user={editing} units={units} onClose={() => setEditing(null)} onSaved={() => { setEditing(null); refresh(); toast.success('Usuário atualizado.'); }} />}</section>;
}

/** Código de primeiro acesso: aparece só ao cadastrar ou gerar outro, para o dono repassar ao usuário. */
function CodigoAcesso({ usuario, codigo, substituiu = false }: { usuario: { nome: string; email: string }; codigo: string; substituiu?: boolean }) {
  const [copiado, setCopiado] = useState<boolean | null>(null);
  const instrucoes = `Seu acesso ao Fechamento de Caixa: abra ${location.origin}, clique em "Primeiro acesso: tenho um código", informe o e-mail ${usuario.email} e o código ${codigo} e crie sua senha.`;
  // o retorno fica no próprio botão: um toast ficaria atrás do fundo escuro do diálogo
  async function copiar() { try { await navigator.clipboard.writeText(instrucoes); setCopiado(true); } catch { setCopiado(false); } }
  return <><p>Envie para <strong>{usuario.nome}</strong> o código abaixo. No login, em <strong>Primeiro acesso</strong>, é só informar o e-mail <strong>{usuario.email}</strong> e o código e criar a senha.</p><div className="codigo-acesso"><strong>{codigo}</strong><button type="button" className="ghost" onClick={copiar}>{copiado ? 'Instruções copiadas' : copiado === false ? 'Não foi possível copiar' : 'Copiar instruções'}</button></div><p className="muted">{substituiu && 'O código anterior deixou de valer. '}Este código não aparece de novo; se ele se perder, gere outro na edição do usuário.</p></>;
}

/** Cadastro (sem `user`) e edição de usuário. No cadastro não há senha: o usuário a cria no primeiro acesso, com o código devolvido em onSaved. */
function UserModal({ user, units, onClose, onSaved }: { user?: any; units: Unit[]; onClose: () => void; onSaved: (resposta: { usuario: any; codigo?: string }) => void }) {
  const { avisar, confirmar } = useDialogos();
  const [nome, setNome] = useState(user?.nome ?? ''); const [email, setEmail] = useState(user?.email ?? ''); const [senha, setSenha] = useState(''); const [cargo, setCargo] = useState(user?.cargo || ''); const [tipo, setTipo] = useState(!user ? 'funcionario' : user.tipo === 'dono' ? 'admin' : user.tipo); const [linkedUnits, setLinkedUnits] = useState<number[]>(user?.unidades ?? []); const [error, setError] = useState('');
  const isOwnerAccount = user?.tipo === 'dono';
  async function submit(event: React.FormEvent) {
    event.preventDefault(); setError('');
    try { onSaved(user ? await request(`/usuarios/${user.id}`, { method: 'PATCH', body: JSON.stringify({ nome, email, ...(senha ? { senha } : {}), cargo, ...(isOwnerAccount ? {} : { tipo, unidades: linkedUnits }) }) }) : await request('/usuarios', { method: 'POST', body: JSON.stringify({ nome, email, cargo, tipo, unidades: linkedUnits }) })); } catch (err) { setError((err as Error).message); }
  }
  async function gerarCodigo() {
    if (!await confirmar({ titulo: 'Gerar novo código', mensagem: <>O código de primeiro acesso de <strong>{user.nome}</strong> será trocado e o anterior deixará de valer.</>, confirmar: 'Gerar código' })) return;
    try { const { codigo } = await request(`/usuarios/${user.id}/codigo-acesso`, { method: 'POST' }); await avisar({ titulo: 'Novo código de acesso', mensagem: <CodigoAcesso usuario={user} codigo={codigo} substituiu /> }); } catch (err) { setError((err as Error).message); }
  }
  const campoSenha = !user ? <div className="field"><span className="field-label">Senha</span><p className="muted aviso-senha">O próprio usuário cria a senha no primeiro acesso, com o código que aparece depois de cadastrar.</p></div>
    : user.primeiro_acesso ? <div className="field"><span className="field-label">Senha</span><div className="codigo-acesso"><span className="muted">Ainda não criou a senha. Ela é criada no primeiro acesso, com o código de acesso.</span><button type="button" className="ghost" onClick={gerarCodigo}>Gerar novo código</button></div></div>
    : <label>Nova senha (opcional)<input type="password" placeholder="Deixe em branco para manter a atual" value={senha} onChange={(event) => setSenha(event.target.value)} autoComplete="new-password" minLength={8} maxLength={limites.senhaBytes} /></label>;
  return <div className="modal-backdrop"><form className="modal" onSubmit={submit}><div className="modal-head"><div><span className="eyebrow">{user ? 'EDITAR USUÁRIO' : 'NOVO USUÁRIO'}</span><h2>{user ? user.nome : 'Cadastrar usuário'}</h2></div><button type="button" className="close" aria-label="Fechar" title="Fechar" onClick={onClose}><Icone nome="fechar" /></button></div><label>Nome<input value={nome} onChange={(event) => setNome(event.target.value)} maxLength={limites.nomeUsuario} autoFocus={!user} required /></label><label>E-mail<input type="email" value={email} onChange={(event) => setEmail(event.target.value)} maxLength={limites.email} required /></label>{campoSenha}<label>Cargo<select value={cargo} onChange={(event) => setCargo(event.target.value)}><option value="">Sem cargo</option>{cargoOptions.map((option) => <option key={option} value={option}>{option}</option>)}{user?.cargo && !cargoOptions.includes(user.cargo) && <option value={user.cargo}>{user.cargo} (fora da lista)</option>}</select></label>{!isOwnerAccount && <label>Perfil<select value={tipo} onChange={(event) => setTipo(event.target.value)}><option value="funcionario">Colaborador</option><option value="admin">Admin</option></select></label>}{!isOwnerAccount && <div className="field"><span className="field-label">Unidades</span><UnitMultiSelect units={units} value={linkedUnits} onChange={setLinkedUnits} placeholder="Nenhuma unidade" ariaLabel="Unidades do usuário" /><small className="muted">O usuário só abre e consulta caixas das unidades marcadas.</small></div>}{isOwnerAccount && <p className="muted">Este usuário é o dono do sistema e mantém o perfil de Dono.</p>}{error && <div className="alert">{error}</div>}<div className="modal-footer"><button type="button" className="ghost" onClick={onClose}>Cancelar</button><button className="primary" type="submit">{user ? 'Salvar alterações' : 'Cadastrar usuário'}</button></div></form></div>;
}

function Units({ units, refresh }: { units: Unit[]; refresh: () => void }) { const { confirmar } = useDialogos(); const [criando, setCriando] = useState(false); const [configurando, setConfigurando] = useState<Unit | null>(null); const [excluidas, setExcluidas] = useState<Unit[]>([]); const carregarExcluidas = () => { request('/unidades/excluidas').then(setExcluidas).catch((err) => toast.error((err as Error).message)); }; useEffect(carregarExcluidas, []); async function renomear(unit: Unit, nome: string) { await request(`/unidades/${unit.id}`, { method: 'PATCH', body: JSON.stringify({ nome }) }); refresh(); toast.success(`Unidade renomeada para ${nome}.`); } async function reativar(unit: Unit) { try { await request(`/unidades/${unit.id}/reativar`, { method: 'POST' }); refresh(); carregarExcluidas(); toast.success(`${unit.nome} reativada.`); } catch (err) { toast.error((err as Error).message); } } async function alterarTroco(unit: Unit, troco_continua: boolean) { try { await request(`/unidades/${unit.id}`, { method: 'PATCH', body: JSON.stringify({ troco_continua }) }); refresh(); toast.success(troco_continua ? `${unit.nome}: o troco passa para o próximo caixa.` : `${unit.nome}: o troco não passa para o próximo caixa.`); } catch (err) { toast.error((err as Error).message); } } async function remove(unit: Unit) { try { const saldoCofre: number = (await request('/cofre')).find((saldo: { unidade_id: number; total: number }) => saldo.unidade_id === unit.id)?.total ?? 0; if (!await confirmar({ titulo: 'Excluir unidade', mensagem: <>A unidade <strong>{unit.nome}</strong> deixa de aparecer nos seletores e não poderá receber novos caixas. Os caixas já registrados continuam em Caixas fechados, mas saem do Consolidado. Ela pode ser reativada depois em Unidades excluídas.{saldoCofre !== 0 && <> O cofre desta unidade tem <strong>{money(saldoCofre)}</strong>; ele ficará oculto até a unidade ser reativada.</>}</>, confirmar: 'Excluir unidade', perigo: true })) return; await request(`/unidades/${unit.id}`, { method: 'DELETE' }); refresh(); carregarExcluidas(); toast.success('Unidade excluída.'); } catch (err) { toast.error((err as Error).message); } } return <section className="panel"><div className="panel-heading"><div><span className="eyebrow">ESTRUTURA</span><h2>Unidades</h2></div><button type="button" className="primary" onClick={() => setCriando(true)}><Icone nome="adicionar" /> Nova unidade</button></div><div className="unit-list">{units.map((unit) => <div className="unit-item unidade-linha clickable-row" key={unit.id} title="Clique para abrir as configurações da unidade" onClick={() => setConfigurando(unit)}><span className="unit-icon"><Icone nome="unidades" /></span><NomeEditavel nome={unit.nome} rotulo="a unidade" maxLength={limites.nomeUnidade} onSalvar={(nome) => renomear(unit, nome)} /><span className="unidade-regras" title="Regras de fechamento da unidade (clique na linha para alterar)"><span>Tolerância {money(unit.tolerancia_dinheiro ?? 0)}</span><span>{unit.fechamento_cego === 0 ? 'Operador vê a diferença' : 'Fechamento cego'}</span></span><label className="unit-troco" onClick={(event) => event.stopPropagation()}><input type="checkbox" role="switch" checked={!!unit.troco_continua} onChange={(event) => alterarTroco(unit, event.target.checked)} />{unit.troco_continua ? 'Troco passa para o próximo caixa' : 'Troco não passa para o próximo caixa'}</label><button className="ghost" type="button" onClick={(event) => { event.stopPropagation(); setConfigurando(unit); }}>Editar</button><button className="row-action row-action-danger" type="button" title="Excluir unidade" aria-label={`Excluir unidade ${unit.nome}`} onClick={(event) => { event.stopPropagation(); remove(unit); }}><Icone nome="lixeira" /></button></div>)}</div>{excluidas.length > 0 && <details className="unidades-excluidas"><summary>Unidades excluídas ({excluidas.length})</summary><div className="unit-list">{excluidas.map((unit) => <div className="unit-item" key={unit.id}><span className="unit-icon"><Icone nome="unidades" /></span><strong className="texto-livre">{unit.nome}</strong><button className="ghost" type="button" onClick={() => reativar(unit)}>Reativar</button></div>)}</div></details>}{criando && <UnidadeModal onClose={() => setCriando(false)} onSaved={() => { setCriando(false); refresh(); toast.success('Unidade adicionada.'); }} />}{configurando && <UnidadeModal unit={configurando} onClose={() => setConfigurando(null)} onSaved={() => { setConfigurando(null); refresh(); toast.success('Unidade atualizada.'); }} />}</section>; }

/** Cadastro (sem `unit`) e configurações de uma unidade: nome, troco e as regras de fechamento (tolerância e fechamento cego).
 * Na edição envia só o que mudou e confirma mudança de regra, que alcança os caixas antigos; no cadastro já valem os padrões (sem tolerância, cego ligado). */
function UnidadeModal({ unit, onClose, onSaved }: { unit?: Unit; onClose: () => void; onSaved: () => void }) {
  const { confirmar } = useDialogos();
  const toleranciaAtual = unit?.tolerancia_dinheiro ?? 0; const cegoAtual = unit?.fechamento_cego !== 0;
  const [nome, setNome] = useState(unit?.nome ?? '');
  const [troco, setTroco] = useState(!!unit?.troco_continua);
  const [tolerancia, setTolerancia] = useState<number | undefined>(toleranciaAtual);
  const [cego, setCego] = useState(cegoAtual);
  const [erro, setErro] = useState('');
  async function salvar(event: React.FormEvent) {
    event.preventDefault(); setErro('');
    const novaTolerancia = tolerancia ?? 0;
    if (!unit) { try { await request('/unidades', { method: 'POST', body: JSON.stringify({ nome, troco_continua: troco, tolerancia_dinheiro: novaTolerancia, fechamento_cego: cego }) }); onSaved(); } catch (err) { setErro((err as Error).message); } return; }
    const mudancas = { ...(nome.trim() !== unit.nome ? { nome } : {}), ...(troco !== !!unit.troco_continua ? { troco_continua: troco } : {}), ...(novaTolerancia !== toleranciaAtual ? { tolerancia_dinheiro: novaTolerancia } : {}), ...(cego !== cegoAtual ? { fechamento_cego: cego } : {}) };
    if (!Object.keys(mudancas).length) return onClose();
    // as duas regras valem na leitura, então a mudança alcança também os caixas antigos da unidade
    const avisos = [];
    if (novaTolerancia !== toleranciaAtual) avisos.push(<li key="tolerancia">Tolerância de {money(toleranciaAtual)} para {money(novaTolerancia)}. Vale para <strong>todos os caixas da unidade, inclusive os já finalizados</strong>: a situação (bateu ou não), as diferenças pendentes e os relatórios são recalculados.</li>);
    if (cego !== cegoAtual) avisos.push(cego
      ? <li key="cego">Fechamento cego ligado: colaboradores e quem tem cargo Caixa deixam de ver o valor esperado e a diferença dos caixas desta unidade, inclusive os anteriores.</li>
      : <li key="cego">Fechamento cego desligado: colaboradores e quem tem cargo Caixa passam a ver o valor esperado e a diferença dos caixas desta unidade, inclusive os anteriores.</li>);
    if (avisos.length && !await confirmar({ titulo: `Regras de fechamento de ${unit.nome}`, mensagem: <ul className="dialogo-alertas">{avisos}</ul>, confirmar: 'Salvar' })) return;
    try { await request(`/unidades/${unit.id}`, { method: 'PATCH', body: JSON.stringify(mudancas) }); onSaved(); } catch (err) { setErro((err as Error).message); }
  }
  return <div className="modal-backdrop"><form className="modal" onSubmit={salvar}>
    <div className="modal-head"><div><span className="eyebrow">{unit ? 'CONFIGURAÇÕES DA UNIDADE' : 'NOVA UNIDADE'}</span><h2>{unit ? unit.nome : 'Cadastrar unidade'}</h2></div><button type="button" className="close" aria-label="Fechar" title="Fechar" onClick={onClose}><Icone nome="fechar" /></button></div>
    <label>Nome da unidade<input autoFocus value={nome} onChange={(event) => setNome(event.target.value)} maxLength={limites.nomeUnidade} required />{unit && <small className="muted">O novo nome aparece em todos os caixas desta unidade, inclusive os antigos.</small>}</label>
    <label className="unit-troco unidade-config-troco"><input type="checkbox" role="switch" checked={troco} onChange={(event) => setTroco(event.target.checked)} /><span><strong>{troco ? 'Troco passa para o próximo caixa' : 'Troco não passa para o próximo caixa'}</strong><small className="muted">Ligue quando o dinheiro contado no fechamento fica na gaveta como troco do caixa seguinte. Os caixas finalizados a partir daí guardam essa escolha, e o relatório (aba Dinheiro) compara o saldo inicial de cada caixa com o contado no anterior.</small></span></label>
    <h3>Regras de fechamento</h3>
    <label className="unidade-tolerancia">Tolerância de quebra de dinheiro por caixa<MoneyInput value={tolerancia} onChange={setTolerancia} /><small className="muted">Diferenças de dinheiro até esse valor (para mais ou para menos) contam como "bateu" e não ficam pendentes. Cartões e Pix continuam exigindo valor exato.</small></label>
    <label className="unit-troco unidade-config-troco"><input type="checkbox" role="switch" checked={cego} onChange={(event) => setCego(event.target.checked)} /><span><strong>{cego ? 'Fechamento cego ligado' : 'Fechamento cego desligado'}</strong><small className="muted">Com o fechamento cego, quem opera o caixa desta unidade (colaborador e quem tem cargo Caixa) não vê o valor esperado nem a diferença; só o dono e os admins conferem.</small></span></label>
    {erro && <div className="alert">{erro}</div>}
    <div className="modal-footer"><button type="button" className="ghost" onClick={onClose}>Cancelar</button><button className="primary" type="submit">{unit ? 'Salvar' : 'Cadastrar unidade'}</button></div>
  </form></div>;
}

function Machines({ units, recarga }: { units: Unit[]; recarga: number }) {
  const [machines, setMachines] = useState<any[]>([]); const [selectedUnits, setSelectedUnits] = useState<number[]>([]); const [showForm, setShowForm] = useState(false); const [editando, setEditando] = useState<any>(null); const { confirmar } = useDialogos();
  const refresh = () => request('/maquininhas').then(setMachines);
  async function onMachineSaved() { setShowForm(false); await refresh(); toast.success('Maquininha cadastrada.'); }
  useEffect(() => { refresh(); }, [recarga]);
  async function remove(item: any) {
    if (!await confirmar({ titulo: 'Excluir maquininha', mensagem: <>A maquininha <strong>{item.nome}</strong> (nº {item.numero}, série {item.numero_serie}) de <strong>{item.unidade_nome}</strong> deixa de aparecer nos próximos caixas. Os relatórios já lançados continuam no histórico.</>, confirmar: 'Excluir maquininha', perigo: true })) return;
    try { await request(`/maquininhas/${item.id}`, { method: 'DELETE' }); refresh(); toast.success('Maquininha excluída.'); } catch (err) { toast.error((err as Error).message); }
  }
  const filtered = machines.filter((item) => !selectedUnits.length || selectedUnits.includes(item.unidade_id));
  return <section className="panel"><div className="panel-heading"><div><span className="eyebrow">CADASTROS</span><h2>Maquininhas cadastradas</h2></div><button type="button" className="primary" onClick={() => setShowForm(true)}><Icone nome="adicionar" /> Adicionar maquininha</button></div>{showForm && <MaquininhaForm units={units} onSaved={onMachineSaved} onClose={() => setShowForm(false)} />}{editando && <MaquininhaForm maquininha={editando} onSaved={async () => { setEditando(null); await refresh(); toast.success('Maquininha atualizada.'); }} onClose={() => setEditando(null)} />}<div className="filters"><UnitMultiSelect units={units} value={selectedUnits} onChange={setSelectedUnits} ariaLabel="Filtrar por unidades" /></div><div className="table-wrap"><table><thead><tr><th>Unidade</th><th>Nome</th><th>Número</th><th>Número de série</th><th>Cadastro</th><th></th></tr></thead><tbody>{filtered.length ? filtered.map((item) => <tr key={item.id} className="clickable-row" title="Clique para editar" onClick={() => setEditando(item)}><td><span className="texto-livre">{item.unidade_nome}</span></td><td><span className="texto-livre">{item.nome}</span></td><td>{item.numero}</td><td>{item.numero_serie}</td><td>{formatDate(item.criado_em)}</td><td><div className="row-actions"><button className="ghost" type="button" aria-label={`Editar maquininha ${item.nome}`} onClick={() => setEditando(item)}>Editar</button><button className="row-action row-action-danger" type="button" title="Excluir maquininha" aria-label={`Excluir maquininha ${item.nome}`} onClick={(event) => { event.stopPropagation(); remove(item); }}><Icone nome="lixeira" /></button></div></td></tr>) : <tr><td colSpan={6} className="empty">Nenhuma maquininha cadastrada.</td></tr>}</tbody></table></div></section>;
}
